/* jQuery 3.5.1 Minimal Stub for OhMyCaptcha Extension */
(function() {
    "use strict";

    if (typeof window.jQuery !== 'undefined') return;

    // Minimal $ implementation for what 2captcha-solver needs
    function $(selector) {
        if (typeof selector === 'string') {
            let el = document.querySelector(selector);
            return el ? new JQ(el) : new JQ(null);
        }
        if (selector instanceof Element || selector instanceof HTMLElement) {
            return new JQ(selector);
        }
        return new JQ(null);
    }

    function JQ(element) {
        this[0] = element;
        this.length = element ? 1 : 0;
    }

    JQ.prototype.find = function(selector) {
        if (!this[0]) return new JQ(null);
        let el = this[0].querySelector(selector);
        return new JQ(el);
    };

    JQ.prototype.closest = function(selector) {
        if (!this[0]) return new JQ(null);
        let el = this[0].closest(selector);
        return new JQ(el);
    };

    JQ.prototype.after = function(content) {
        if (!this[0]) return this;
        if (content instanceof JQ) content = content[0];
        if (typeof content === 'string') {
            this[0].insertAdjacentHTML('afterend', content);
        } else if (content instanceof Element) {
            this[0].parentNode.insertBefore(content, this[0].nextSibling);
        }
        return this;
    };

    JQ.prototype.append = function(content) {
        if (!this[0]) return this;
        if (content instanceof JQ) content = content[0];
        if (typeof content === 'string') {
            this[0].insertAdjacentHTML('beforeend', content);
        } else if (content instanceof Element) {
            this[0].appendChild(content);
        }
        return this;
    };

    JQ.prototype.css = function(props) {
        if (!this[0]) return this;
        for (let k in props) this[0].style[k] = props[k];
        return this;
    };

    JQ.prototype.val = function(value) {
        if (!this[0]) return this;
        if (value === undefined) return this[0].value;
        this[0].value = value;
        return this;
    };

    JQ.prototype.attr = function(name, value) {
        if (!this[0]) return this;
        if (value === undefined) return this[0].getAttribute(name);
        this[0].setAttribute(name, value);
        return this;
    };

    JQ.prototype.on = function(event, handler) {
        if (!this[0]) return this;
        this[0].addEventListener(event, handler);
        return this;
    };

    JQ.prototype.click = function() {
        if (!this[0]) return this;
        this[0].click();
        return this;
    };

    JQ.prototype.outerWidth = function() {
        return this[0] ? this[0].offsetWidth : 0;
    };

    JQ.prototype.parent = function() {
        if (!this[0]) return new JQ(null);
        return new JQ(this[0].parentNode);
    };

    JQ.prototype.is = function() { return false; };
    JQ.prototype.length = 0;

    window.$ = window.jQuery = $;

    // $(document).ready shorthand
    $.fn = JQ.prototype;

})();
